(()=>{const $=id=>document.getElementById(id),n=id=>parseFloat($(id).value);function go(){const sex=$('sex').value,a=n('age'),w=n('weight'),h=n('height'),f=$('factor').value==='custom'?n('custom'):parseFloat($('factor').value);$('custom').disabled=$('factor').value!=='custom';if(![a,w,h,f].every(Number.isFinite)||a<18||w<=0||h<=0||f<=0){$('note').textContent='Enter valid adult age, height, weight and activity factor.';$('note').className='helper danger';return;}const ree=10*w+6.25*h-5*a+(sex==='m'?5:-161),t=ree*f;$('ree').textContent=Math.round(ree)+' kcal/day';$('tdee').textContent=Math.round(t)+' kcal/day';$('af').textContent=f.toFixed(3);$('note').textContent='TDEE is a model estimate. Activity factors are broad categories, and individual energy expenditure can differ substantially.';$('note').className='helper';}
